// Mock credentials implementation
class MockCredentials : public ICredentials {
private:
    std::string m_public_key;
    std::string m_private_key;

public:
    MockCredentials(const std::string& public_key, const std::string& private_key)
        : m_public_key(public_key), m_private_key(private_key) {}

    ProtocolType getType() const noexcept override {
        return ProtocolType::ZQTP;
    }

    std::string get(CredentialType type) const override {
        switch (type) {
            case CredentialType::PUBLIC_KEY:
                return m_public_key;
            case CredentialType::PRIVATE_KEY:
                return m_private_key;
            case CredentialType::SERVER_KEY:
                return m_public_key; // For testing, use public key as server key
            default:
                return "";
        }
    }

    bool has(CredentialType type) const noexcept override {
        return type == CredentialType::PUBLIC_KEY || 
               type == CredentialType::PRIVATE_KEY || 
               type == CredentialType::SERVER_KEY;
    }
};

