std::unique_ptr<ICommunicator> make_client(
    rust::Str host,
    rust::Str endpoint,
    std::uint32_t sid,
    std::int64_t poll_timeout_ms) {
    
    try {
        // Convert rust::Str to std::string
        std::string host_str(host.data(), host.size());
        std::string endpoint_str(endpoint.data(), endpoint.size());
        
        // Create socket options
        SocketOptions socket_options;
        socket_options.scheme = URIScheme::TCP;
        socket_options.class_type = SocketClassType::CLIENT;
        socket_options.direction_type = SocketDirectionalityType::BIDIRECTIONAL;
        socket_options.communication_type = SocketCommunicationType::ASYNCHRONOUS;
        socket_options.connection_life = SocketConnectionLife::PERSISTENT;
        socket_options.connection_security = SocketConnectionSecurity::INSECURE;
        socket_options.protocol_type = ProtocolType::ZQTP;
        socket_options.host = host_str;
        
        // Parse port from endpoint if provided
        if (!endpoint_str.empty()) {
            try {
                socket_options.port = static_cast<uint16_t>(std::stoi(endpoint_str));
            } catch (const std::exception& e) {
                std::cerr << "[WARN] Could not parse port from endpoint: " << endpoint_str << std::endl;
            }
        }
        
        socket_options.local_id = "repo-server-client-" + std::to_string(sid);
        
        // Create log context
        LogContext log_context;
        log_context.thread_name = "repo-client";
        log_context.correlation_id = "client-" + std::to_string(sid);
        log_context.thread_id = sid;
        
        // Create mock credentials for testing
        MockCredentials credentials(MOCK_PUBLIC_KEY, MOCK_PRIVATE_KEY);
        
        // Create communicator factory and communicator
        CommunicatorFactory factory(log_context);
        auto communicator = factory.create(socket_options, credentials, 
                                         static_cast<uint32_t>(poll_timeout_ms), 
                                         poll_timeout_ms);
        
        if (!communicator) {
            std::cerr << "[ERROR] Failed to create communicator" << std::endl;
            return nullptr;
        }
        
        std::cerr << "[INFO] Created communicator with ID: " << communicator->id() 
                  << " for address: " << communicator->address() << std::endl;
        
        return communicator;
        
    } catch (const std::exception& e) {
        std::cerr << "[ERROR] Failed to create client: " << e.what() << std::endl;
        return nullptr;
    }
}

std::unique_ptr<IMessage> create_version_request() {
    try {
        if (!g_message_factory) {
            std::cerr << "[ERROR] Message factory not initialized" << std::endl;
            return nullptr;
        }
        
        // Create a simple string message for version request
        auto message = g_message_factory->create(MessageType::STRING);
        if (!message) {
            std::cerr << "[ERROR] Failed to create message envelope" << std::endl;
            return nullptr;
        }
        
        // Set the string payload
        message->setPayload("VERSION_REQUEST");
        
        // Set message attributes
        message->set(MessageAttribute::STATE, MessageState::REQUEST);
        
        return message;
        
    } catch (const std::exception& e) {
        std::cerr << "[ERROR] Failed to create version request: " << e.what() << std::endl;
        return nullptr;
    }
}

std::unique_ptr<IMessage> create_version_reply() {
    try {
        if (!g_message_factory) {
            std::cerr << "[ERROR] Message factory not initialized" << std::endl;
            return nullptr;
        }
        
        // Create a simple string message for version reply
        auto message = g_message_factory->create(MessageType::STRING);
        if (!message) {
            std::cerr << "[ERROR] Failed to create message envelope" << std::endl;
            return nullptr;
        }
        
        // Set the string payload with version info
        std::string version_info = R"({
            "release_year": 2024,
            "release_month": 12,
            "release_day": 1,
            "api_major": 1,
            "api_minor": 0,
            "api_patch": 0,
            "component_major": 1,
            "component_minor": 0,
            "component_patch": 0
        })";
        
        message->setPayload(version_info);
        
        // Set message attributes
        message->set(MessageAttribute::STATE, MessageState::RESPONSE);
        
        return message;
        
    } catch (const std::exception& e) {
        std::cerr << "[ERROR] Failed to create version reply: " << e.what() << std::endl;
        return nullptr;
    }
}

